function edit(item=null,type='Game',title=''){const old=item?C.meta(item):{},d=dialog(item?'Edit your story':'Manual story',`<form id="living-edit-form"><div class="living-form-grid"><label>Title<input name="title" maxlength="150" required value="${E(item?.title||title)}"></label><label>Format<select name="type" ${item?'disabled':''}>${C.TYPES.map(t=>`<option value="${t}" ${t===(item?.type||type)?'selected':''}>${LABEL[t]}</option>`).join('')}</select></label><label>Author / creator<input name="author" maxlength="300" value="${E(old.author||old.creators||'')}"></label><label>Release year<input name="year" type="number" min="0" max="2200" value="${old.year||0}"></label><label>Genres / mood tags<input name="genres" maxlength="400" value="${E(old.genres||'')}"></label><label>Platform / edition<input name="edition" maxlength="300" value="${E(old.edition||old.platforms||'')}"></label><label>Edition page count (books)<input name="pages" type="number" min="0" max="100000" value="${item?.book?.pages||0}"></label><label>Episodes this season (TV / anime)<input name="episodes" type="number" min="0" max="100000" value="${item?.watch?.totalEpisodes||0}"></label><label>Rating (0–10)<input name="rating" type="number" min="0" max="10" step="0.5" value="${Number(old.rating||item?.rating)||0}"></label></div><label>Description<textarea name="description" rows="4" maxlength="6000">${E(old.description||'')}</textarea></label><label>Your review / notes<textarea name="note" rows="3" maxlength="2000">${E(item?.note||'')}</textarea></label><label>Custom cover (PNG, JPEG or WebP, up to 900 KB)<input name="cover" type="file" accept="image/png,image/jpeg,image/webp"></label><p id="living-upload-status" role="status"></p><label><input name="clearArt" type="checkbox"> Remove saved artwork</label><footer><button class="button button-primary" type="submit">Save story</button><button class="button button-quiet" type="button" data-close>Cancel</button></footer></form>`);if(item)d._record={id:item.id,original:JSON.stringify(item)};let uploaded='';const form=d.querySelector('form');const specialize=()=>{const k=item?.type||form.elements.type.value;form.elements.pages.closest('label').hidden=k!=='Book';form.elements.episodes.closest('label').hidden=!['Show','Anime'].includes(k);};form.elements.type.onchange=specialize;specialize();form.elements.cover.onchange=async e=>{const file=e.target.files[0],save=form.querySelector('[type=submit]');if(!file)return;save.disabled=true;try{if(file.size>900000||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Choose a PNG, JPEG or WebP below 900 KB.');const src=URL.createObjectURL(file),img=new Image();try{await new Promise((ok,no)=>{img.onload=ok;img.onerror=()=>no(Error('Image could not be decoded.'));img.src=src;});if(img.width*img.height>16000000)throw Error('Image dimensions are too large.');const c=document.createElement('canvas'),scale=Math.min(1,800/img.width,1200/img.height);c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);uploaded=c.toDataURL('image/jpeg',.8);if(uploaded.length>550000)throw Error('Choose a smaller image.');d.querySelector('#living-upload-status').textContent='Custom cover ready. Save to keep it.';}finally{URL.revokeObjectURL(src);}}catch(e){uploaded='';err(d,e);}finally{save.disabled=false;}};
form.onsubmit=e=>{e.preventDefault();const f=new FormData(form),k=item?.type||f.get('type'),name=C.text(f.get('title'),150);if(rows().some(x=>x.id!==item?.id&&(x.type||'Game')===k&&C.norm(x.title)===C.norm(name))){err(d,Error('This story is already saved.'));return;}const x=item?structuredClone(item):{id:'living-'+crypto.randomUUID(),type:k,status:'Want to Try',createdAt:new Date().toISOString()};x.title=name;x.note=C.text(f.get('note'),2000);const next={...C.sanitizeMetadata(old)},manual=new Set(next.manualFields);for(const key of ['description','author','year','genres','edition']){const value=key==='year'?C.num(f.get(key),2200):C.text(f.get(key),key==='description'?6000:400);if(value!==(old[key]|| (key==='year'?0:'')))manual.add(key);next[key]=value;}if(uploaded||f.has('clearArt')){next.artwork=uploaded||'';manual.add('artwork');if(f.has('clearArt')){delete x.background_image;if(x.watch)delete x.watch.cover;if(x.book)delete x.book.coverId;}}if(k==='Game'&&next.edition)next.platforms=next.edition;next.manualFields=[...manual];next.updatedAt=new Date().toISOString();next.rating=Number(f.get('rating'))||0;x.rating=next.rating;x.metadata184=next;if(k==='Book')x.book={...x.book,author:next.author,pages:C.num(f.get('pages')),genres:next.genres,rating:next.rating};if(['Movie','Show','Anime'].includes(k))x.watch={...x.watch,totalEpisodes:C.num(f.get('episodes')),genres:next.genres,rating:next.rating};const ok=mutate(v=>{const i=v.backlog.findIndex(a=>a.id===x.id);if(i<0)v.backlog.unshift(x);else v.backlog[i]=x;});if(ok)d.close();else err(d,Error('Save failed. Your earlier workspace is intact; keep this form open and retry.'));};}
function details(id){const x=find(id);if(!x)return;const m=C.meta(x),rel=C.related(data(),x),d=dialog(x.title,`<div class="living-detail">${art(x)}<div><p>${E(x.type)} · ${E(x.status)} · ${E(m.year||'Year unknown')}</p><p>${E(m.author||m.creators||'')}</p><p>${E(m.description||'Add a synopsis or find details from a catalog.')}</p><p>${E(m.genres||'')}</p><p>${E(m.platforms||'')} ${E(m.edition||'')} ${m.isbn?'ISBN '+E(m.isbn):''}</p>${m.cast?`<details><summary>Cast</summary><p>${E(m.cast)}</p></details>`:''}${m.alternativeTitles?`<p>Also known as: ${E(m.alternativeTitles)}</p>`:''}${C.safeLink(m.sourceUrl)?`<a href="${E(m.sourceUrl)}" target="_blank" rel="noopener noreferrer">${E(m.provider||'Catalog')} source ↗</a>`:''}<p class="small-note">${E(m.attribution||'Your private library record.')}</p><div class="living-actions">${btn('Edit','edit',id)}${btn('Find artwork & details','match',id)}${btn('Log progress','progress',id)}${btn('Diary, episodes & editions','media-history',id)}${btn('Start session','start',id)}${btn('Save cover offline','cache',id)}${btn('Remove story','remove',id)}</div></div></div><details><summary>Your notes & journal</summary><p>${E(x.note||'No review yet.')}</p>${C.arr(x.book?.sessions).slice(-15).map(s=>`<p>${E(s.date?.slice(0,10))} · page ${C.num(s.page)} · ${E(s.note)}</p>`).join('')}</details><h3>Across your worlds</h3>${rel.map(r=>`<p>${E(r.item.title)} · ${E(LABEL[r.item.type])}<br><small>Similarity suggestion: shared ${E(r.shared.join(', '))} tags. No adaptation relationship is implied.</small></p>`).join('')||'<p>Save different formats with shared genres to see thematic suggestions.</p>'}${/witcher|last wish|blood of elves/i.test(x.title)?'<p><b>Verified franchise connection:</b> The Witcher books inspired games and television. <a href="https://www.hachettebookgroup.com/series/andrzej-sapkowski/the-witcher/" target="_blank" rel="noopener noreferrer">Publisher source ↗</a></p>':''}`);d.addEventListener('click',e=>{const b=e.target.closest('[data-living]');if(!b)return;if(['edit','match','progress','start','remove','media-history'].includes(b.dataset.living))d.close();action(b.dataset.living,b.dataset.id);});}
function progressDialog(id){const x=find(id);if(!x)return;const d=dialog('Log progress · '+x.title,`<form id="living-progress-form">${!C.isFilm(x)?`<label>${x.type==='Book'?'Page reached':x.type==='Game'?'Total hours played':'Episodes watched this season'}<input name="progress" type="number" min="0" max="100000" value="${x.type==='Book'?C.num(x.book?.progress):x.type==='Game'?C.num(x.hours):C.num(x.watch?.episodes)}" required></label>`:''}${['Show','Anime'].includes(x.type)&&!C.isFilm(x)?`<label>Season<input name="season" type="number" min="1" max="1000" value="${C.num(x.watch?.season)||1}"></label>`:''}${x.type==='Book'?'<label>Reading journal<textarea name="journal" maxlength="1000" rows="3"></textarea></label>':''}<label class="living-check"><input name="finished" type="checkbox" ${C.finished(x)?'checked':''}> I completed this ${x.type==='Book'?'book':C.isFilm(x)?'film':x.type==='Game'?'game':'season'}</label><p>Corrections reconcile related XP. Repeating a milestone never creates an extra award.</p><footer><button class="button button-primary" type="submit">Save progress</button><button type="button" class="button button-quiet" data-close>Cancel</button></footer></form>`);d._record={id:x.id,original:JSON.stringify(x)};d.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);try{const v={progress:C.num(f.get('progress')),season:C.num(f.get('season'))||1,finished:f.has('finished'),journal:f.get('journal')};C.progress(structuredClone(data()),id,v);if(mutate(x=>C.progress(x,id,v)))d.close();else err(d,Error('Could not save. Earlier progress is intact.'));}catch(e){err(d,e);}};}
function preferences(){const p=prefs(),d=dialog('Make this world yours',`<form id="living-preferences"><label class="living-check"><input name="online" type="checkbox" ${p.online?'checked':''}> Enable automatic title lookups. Only titles and categories go to providers.</label><label class="living-check"><input name="moodConsent" type="checkbox" ${p.moodConsent?'checked':''}> Use my voluntary mood choice or latest mood check-in for local suggestions.</label><label>Suggestion mood<select name="mood"><option value="">Use latest voluntary check-in</option>${Object.keys(C.MOODS).map(m=>`<option ${m===p.mood?'selected':''}>${E(m)}</option>`).join('')}</select></label><fieldset><legend>Hide these formats from suggestions</legend>${C.TYPES.map(t=>`<label class="living-check"><input name="hideKinds" type="checkbox" value="${t}" ${p.hideKinds.includes(t)?'checked':''}> ${LABEL[t]}</label>`).join('')}</fieldset><label class="living-check"><input name="reminders" type="checkbox" ${p.reminders?'checked':''}> Show gentle break reminders during sessions</label><label>Minutes between reminders<input name="breakMinutes" type="number" min="5" max="180" value="${p.breakMinutes}"></label><fieldset><legend>Optional reminders</legend>${[['eyes','Look away from the screen'],['water','Have water if you want'],['stretch','Stretch if comfortable'],['posture','Check your posture'],['stand','Stand if comfortable'],['rest','Pause and rest']].map(([k,v])=>`<label class="living-check"><input name="breakTypes" type="checkbox" value="${k}" ${p.breakTypes.includes(k)?'checked':''}> ${v}</label>`).join('')}</fieldset><p>Suggestions are choices, not treatment. No mood, activity level or health condition is inferred. Nothing goes to a recommendation service.</p><footer><button class="button button-primary" type="submit">Save preferences</button>${btn('Reset dismissed suggestions','reset-suggestions')}</footer></form>`);d._preferences=JSON.stringify(prefs());d.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(mutate(x=>Object.assign(x.living184.preferences,{online:f.has('online'),moodConsent:f.has('moodConsent'),mood:f.get('mood'),hideKinds:f.getAll('hideKinds'),reminders:f.has('reminders'),breakMinutes:Math.max(5,C.num(f.get('breakMinutes'),180)),breakTypes:f.getAll('breakTypes')})))d.close();else err(d,Error('Could not save preferences.'));};d.querySelector('[data-living=reset-suggestions]').onclick=()=>{if(mutate(x=>{x.living184.preferences.dismissed=[];x.living184.preferences.lessTags=[];}))ctx.toast('Suggestions reset.','success');};}
function rewards(){const labels={movie:'Film completion',episode:'TV / anime episode',season:'Season completion',bookPage:'Each 25 pages (first 500)',book:'Book completion',game:'Game completion',review:'Review (80+ characters)',session:'Session (5+ minutes)',wellness:'Chosen break',creative:'Creative quest',discovery:'Discovery challenge'},d=dialog('Balance your rewards',`<form><p>Future milestones use these values (0–100). Existing awards retain their original values. No rewards depend on weight, calories or missed days.</p><div class="living-form-grid">${Object.entries(living().rewards).map(([k,v])=>`<label>${E(labels[k]||k)}<input name="${k}" type="number" min="0" max="100" value="${v}"></label>`).join('')}</div><button type="submit" class="button button-primary">Save future rewards</button></form>`);d.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(mutate(x=>{for(const k of Object.keys(x.living184.rewards))x.living184.rewards[k]=C.num(f.get(k),100);}))d.close();};}
async function cache(id){const x=find(id);if(!x)return;const m=C.meta(x),src=cover(x);if(!src||src.startsWith('data:')||src.startsWith('/api/')){ctx.toast(src?'This cover is already stored locally.':'Choose artwork first.');return;}if(!m.cacheAllowed){ctx.toast('Offline copying is disabled for this source. Use a custom upload you have permission to keep, or review provider setup.','error');return;}try{const r=await fetch('/api/artwork/cache',{method:'POST',headers:{'Content-Type':'application/json','X-Rowanvale-Intent':'cache-artwork'},body:JSON.stringify({url:src}),signal:AbortSignal.timeout(18000)}),v=await r.json();if(!r.ok)throw Error(v.error||'Artwork download failed.');if(mutate(d=>{const x=d.backlog.find(x=>x.id===id);x.metadata184={...x.metadata184,originalArtwork:src,artwork:v.src};}))ctx.toast('Cover stored on this device. Include artwork in your ZIP backup.','success');}catch(e){ctx.toast(e.message,'error');}}
const pause=(ms,signal)=>new Promise((resolve,reject)=>{const t=setTimeout(resolve,ms);signal?.addEventListener('abort',()=>{clearTimeout(t);reject(new DOMException('Cancelled','AbortError'));},{once:true});});
function updateBulk(){const el=document.getElementById('living-bulk-results');if(el)el.innerHTML=bulkHTML();const p=document.getElementById('living-bulk-progress');if(p){p.max=Math.max(1,bulk.length);p.value=bulk.filter(x=>x.state!=='queued').length;}const s=document.getElementById('living-bulk-status');if(s)s.textContent=bulk.filter(x=>x.state!=='queued').length+' / '+bulk.length+' checked. '+(busy?'You can cancel at any time.':'Review matches before applying.');}
async function scan(retry=false){if(busy)return;if(!prefs().online){ctx.toast('Enable online title lookups in preferences before enhancing your library.','error');return;}const scope=document.getElementById('living-bulk-scope')?.value||'missing';if(!retry)bulk=rows().filter(x=>scope!=='missing'||!cover(x)||!C.meta(x).description).slice(0,12).map(x=>({id:x.id,title:x.title,state:'queued',approved:false,refresh:scope==='refresh'}));else for(const b of bulk)if(['failed','cancelled'].includes(b.state)){b.state='queued';b.error='';}
busy=true;abort=new AbortController();const signal=abort.signal;ctx.render();try{for(const b of bulk.filter(x=>x.state==='queued')){if(signal.aborted)break;const x=find(b.id);if(!x){b.state='removed';continue;}try{if(scope==='broken'&&cover(x)){await new Promise((resolve,reject)=>{const img=new Image(),t=setTimeout(()=>reject(Error('Artwork did not load. Choose a new match.')),8000);img.onload=()=>{clearTimeout(t);resolve();};img.onerror=()=>{clearTimeout(t);reject(Error('Artwork unavailable. Choose a new match.'));};img.src=cover(x);});b.state='artwork available';continue;}
const v=await request('/api/metadata/search?type='+encodeURIComponent(x.type||'Game')+'&q='+encodeURIComponent(x.title.slice(0,120)),signal),match=v.results.find(r=>C.norm(r.title)===C.norm(x.title))||v.results[0];if(!match)throw Error('No match. Try a different title.');b.candidate=match;if(match.sourceId&&['Open Library','IGDB','TMDB','Steam'].includes(match.provider)){try{const detail=await request('/api/metadata/details?type='+encodeURIComponent(x.type||'Game')+'&provider='+encodeURIComponent(match.provider)+'&id='+encodeURIComponent(match.sourceId),signal);b.candidate={...match,...Object.fromEntries(Object.entries(detail.result).filter(([,v])=>v!==''&&v!==0))};}catch(e){if(e.name==='AbortError')throw e;b.error='Details unavailable: '+e.message;}}b.state='awaiting your match confirmation';}catch(e){if(e.name==='AbortError')break;b.error=e.message;b.state='failed';}finally{updateBulk();}await pause(1250,signal);}}catch(e){if(e.name!=='AbortError')message=e.message;}finally{for(const b of bulk)if(b.state==='queued')b.state='cancelled';busy=false;ctx.render();}}
function start(id){const x=find(id);if(!x)return;if(living().sessions.some(s=>!s.endedAt)){tab='sessions';message='Finish or discard the active session before starting another.';ctx.render();return;}if(mutate(d=>d.living184.sessions.push({id:crypto.randomUUID(),itemId:id,title:x.title,type:x.type,startedAt:Date.now(),breaks:[],lastReminder:Date.now()}))){tab='sessions';ctx.render();}}
function tick(){const s=living()?.sessions.find(s=>!s.endedAt);if(!s)return;const node=document.getElementById('living-timer');if(node)node.textContent=Math.max(0,Math.floor((Date.now()-s.startedAt)/60000))+' min';const reminder=document.getElementById('living-reminder');if(reminder&&prefs().reminders&&Date.now()-(s.lastReminder||s.startedAt)>=prefs().breakMinutes*60000){const a=prefs().breakTypes,labels={eyes:'Look at something away from the screen.',water:'Have some water if you want.',stretch:'Stretch if comfortable.',posture:'Find a comfortable position.',stand:'Stand if comfortable and safe.',rest:'Pause for a moment.'};reminder.textContent=a.length?'Optional break: '+labels[a[Math.floor((Date.now()-s.startedAt)/(prefs().breakMinutes*60000))%a.length]]:'';}}
